describe("calculations", () => {
	test.each(legacyCases)("$kind $args", ({ kind, args, steps, result }) => {
		const calculation = calculators[kind](...args)

		expect(calculation.steps).toEqual(steps)
		expect(calculation.result).toBe(result)
	})

	test.each(legacyErrors)("$kind $args throws", ({ kind, args, message }) => {
		expect(() => calculators[kind](...args)).toThrow(new CalculationError(message))
	})

	test("charge rejects a second charge of zero instead of printing Infinity", () => {
		expect(() => calculateCharge("9", "1", "0", "2")).toThrow("Second charge cannot be zero")
	})

	test("an overflow is reported instead of printing Infinity", () => {
		expect(() => calculateForce("9", "1e300", "1e300", "1")).toThrow("The result is out of range")
	})
})

describe("isValidNumber", () => {
	test.each(["1", "-1", "+1", "1.5", ".5", "1e3", "1.6e-19", "-2.5e+10"])("accepts %s", value => {
		expect(isValidNumber(value)).toBe(true)
	})

	test.each(["", "abc", "1,5", "5.", "1E3", ".5e3", "1e", "--1", "1 2", "Infinity"])("rejects %j", value => {
		expect(isValidNumber(value)).toBe(false)
	})
})
